using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using MultiFPS.UI;using ROM.Progression;
namespace ROM.UI.Gameplay {
 public sealed class RiftQuestMapPinView:MonoBehaviour,IPointerEnterHandler,IPointerExitHandler,ISelectHandler,IDeselectHandler {
  public RectTransform Rect{get;private set;}public RectTransform HitRect{get;private set;}public GameObject TooltipOwner=>HitRect?HitRect.gameObject:gameObject;public string Key{get;private set;}public string Title{get;private set;}public string Description{get;private set;}public Vector3 World{get;private set;}public RiftQuestPinKind Kind{get;private set;}public bool Minimap{get;private set;}
  Text glyph,badge;Image stem,anchor;RiftMapSurface surface;RiftHUDGraphic diamond;bool hovered,focused,pointerFocus;Color color;
  public void Initialize(Transform parent,bool mini,Font font){Minimap=mini;Rect=(RectTransform)transform;Rect.SetParent(parent,false);Rect.anchorMin=Rect.anchorMax=Rect.pivot=new Vector2(.5f,.5f);Rect.sizeDelta=Vector2.one*(mini?20:25);HitRect=new GameObject("Quest pin hit target",typeof(RectTransform)).GetComponent<RectTransform>();HitRect.SetParent(Rect,false);HitRect.anchorMin=HitRect.anchorMax=HitRect.pivot=Vector2.one*.5f;HitRect.sizeDelta=Rect.sizeDelta;var line=new GameObject("Geographic pin connector",typeof(RectTransform)).GetComponent<RectTransform>();line.SetParent(Rect,false);line.anchorMin=line.anchorMax=line.pivot=Vector2.one*.5f;stem=line.gameObject.AddComponent<Image>();stem.raycastTarget=false;var dot=new GameObject("Exact geographic anchor",typeof(RectTransform)).GetComponent<RectTransform>();dot.SetParent(Rect,false);dot.anchorMin=dot.anchorMax=dot.pivot=Vector2.one*.5f;dot.sizeDelta=Vector2.one*3;anchor=dot.gameObject.AddComponent<Image>();anchor.raycastTarget=false;HitRect.SetAsLastSibling();SetOffset(0);surface=HitRect.gameObject.AddComponent<RiftMapSurface>();surface.Fill=new Color(.035f,.028f,.06f,.96f);surface.Radius=7;surface.raycastTarget=true;var button=gameObject.AddComponent<Button>();button.targetGraphic=surface;button.navigation=new Navigation{mode=Navigation.Mode.None};button.onClick.AddListener(Show);var shape=new GameObject("Objective diamond",typeof(RectTransform)).GetComponent<RectTransform>();shape.SetParent(HitRect,false);shape.anchorMin=shape.anchorMax=shape.pivot=new Vector2(.5f,.5f);shape.sizeDelta=Vector2.one*(mini?10:12);diamond=shape.gameObject.AddComponent<RiftHUDGraphic>();diamond.Shape=HUDShape.Diamond;diamond.raycastTarget=false;glyph=Label("Quest state",font,mini?17:21);glyph.rectTransform.anchoredPosition=new Vector2(0,1);badge=Label("Grouped count",font,9);badge.rectTransform.anchoredPosition=new Vector2(mini?8:10,mini?-8:-10);badge.rectTransform.sizeDelta=new Vector2(21,14);badge.color=Color.white;}
  Text Label(string name,Font font,int size){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(HitRect,false);r.anchorMin=r.anchorMax=Vector2.one*.5f;r.pivot=Vector2.one*.5f;r.sizeDelta=Rect.sizeDelta;var t=r.gameObject.AddComponent<Text>();t.font=font;t.fontSize=size;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;var shadow=r.gameObject.AddComponent<Shadow>();shadow.effectColor=Color.black;shadow.effectDistance=new Vector2(1,-1);return t;}
  public void Bind(string key,Vector3 world,RiftQuestPinKind kind,string title,string description,int count){bool changed=Key!=key||Title!=title||Description!=description;Key=key;World=world;Kind=kind;Title=title;Description=description;color=kind==RiftQuestPinKind.Objective?new Color(.3f,.88f,1):kind==RiftQuestPinKind.TurnIn?new Color(1,.85f,.35f):new Color(.9f,.72f,.3f);surface.Border=color;stem.color=anchor.color=new Color(color.r,color.g,color.b,.7f);surface.SetVerticesDirty();glyph.text=kind==RiftQuestPinKind.Objective?"":kind==RiftQuestPinKind.TurnIn?"?":"!";glyph.color=color;diamond.gameObject.SetActive(kind==RiftQuestPinKind.Objective);diamond.color=color;diamond.SetVerticesDirty();badge.text=count>1?Mathf.Min(99,count).ToString():"";gameObject.name=(Minimap?"Minimap":"Map")+" quest pin · "+kind;gameObject.SetActive(true);if(changed&&(hovered||focused))Show();}
  public void SetOffset(float y){if(!HitRect)return;HitRect.anchoredPosition=new Vector2(0,y);if(stem){stem.enabled=Mathf.Abs(y)>.1f;var r=(RectTransform)stem.transform;r.anchoredPosition=new Vector2(0,y*.5f);r.sizeDelta=new Vector2(1,Mathf.Abs(y));}if(anchor)anchor.enabled=Mathf.Abs(y)>.1f;}
  void Show(){if(gameObject.activeInHierarchy)RiftAbilityTooltip.ShowText(TooltipOwner,Title,Description,"",color);}
  public void OnPointerEnter(PointerEventData e){hovered=true;pointerFocus=true;Show();}public void OnPointerExit(PointerEventData e){hovered=false;if(!focused||pointerFocus)RiftAbilityTooltip.Hide(TooltipOwner);}public void OnSelect(BaseEventData e){focused=true;pointerFocus=hovered||e is PointerEventData;Show();}public void OnDeselect(BaseEventData e){focused=false;if(!hovered)RiftAbilityTooltip.Hide(TooltipOwner);}void OnDisable(){hovered=focused=pointerFocus=false;RiftAbilityTooltip.Hide(TooltipOwner);}void OnDestroy(){RiftAbilityTooltip.Hide(TooltipOwner);}
 }
 [DefaultExecutionOrder(1100)]public sealed class RiftQuestMapPins:MonoBehaviour {
  public const int MapLimit=24,MinimapLimit=12;public IReadOnlyList<RiftQuestPinEntry> Entries=>entries;
  RiftFieldUI field;RiftHUDMinimap mini;RectTransform worldLayer,miniLayer;readonly RiftQuestPinModel model=new RiftQuestPinModel();List<RiftQuestPinEntry> entries=new List<RiftQuestPinEntry>();readonly List<RiftQuestMapPinView> worldViews=new List<RiftQuestMapPinView>(),miniViews=new List<RiftQuestMapPinView>();float next;bool dirty=true;Font font;
  sealed class Group{public RiftQuestPinEntry Main;public Vector2 Pixel;public readonly List<RiftQuestPinEntry> Items=new List<RiftQuestPinEntry>();}
  void Awake(){field=GetComponent<RiftFieldUI>();font=field&&field.Theme&&field.Theme.BodyFont?field.Theme.BodyFont:Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");RiftJournalView.Changed+=Changed;}
  void Changed(){dirty=true;}void OnDestroy(){RiftJournalView.Changed-=Changed;foreach(var v in worldViews.Concat(miniViews))if(v)RiftAbilityTooltip.Hide(v.TooltipOwner);if(worldLayer)Destroy(worldLayer.gameObject);if(miniLayer)Destroy(miniLayer.gameObject);}
  RectTransform Layer(Transform parent,string name){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=Vector2.one*.5f;r.anchoredPosition=r.sizeDelta=Vector2.zero;return r;}
  void LateUpdate(){var player=ClientFrontend.ClientPlayerInstance;var actor=player?player.MyCharacter:null;if(!field||!actor||actor.Health.CurrentHealth<=0||ClientFrontend.Hub){Hide(worldViews);Hide(miniViews);return;}if(!worldLayer)worldLayer=Layer(field.Content,"Quest pins world map");if(!mini)mini=FindFirstObjectByType<RiftHUDMinimap>();if(mini&&mini.Map&&!miniLayer)miniLayer=Layer(mini.Map.rectTransform,"Quest pins minimap");if(dirty||Time.unscaledTime>=next){dirty=false;next=Time.unscaledTime+.2f;var state=RiftJournalView.Read();entries=state.CharacterId==player.PlayerInfo.CharacterId?model.Build(state,RiftJournalCatalog.Load,actor):new List<RiftQuestPinEntry>();Refresh(field.MapOpen,actor.transform.position);}if(!field.MapOpen)Hide(worldViews);else{worldLayer.SetAsLastSibling();float zoom=Mathf.Max(.01f,field.Content.localScale.x);foreach(var v in worldViews)if(v&&v.gameObject.activeSelf){v.Rect.localScale=Vector3.one/zoom;var screen=RectTransformUtility.WorldToScreenPoint(null,v.Rect.position);var playerScreen=RectTransformUtility.WorldToScreenPoint(null,field.PlayerMarker.position);float offset=0;if((screen-playerScreen).sqrMagnitude<42*42){var corners=new Vector3[4];field.Viewport.GetWorldCorners(corners);float desired=playerScreen.y+42;if(desired>corners[2].y-18)desired=playerScreen.y-42;offset=(desired-screen.y)/Mathf.Max(.01f,v.Rect.lossyScale.y);}v.SetOffset(offset);}if(field.PlayerMarker)field.PlayerMarker.SetAsLastSibling();}if(mini&&miniLayer){foreach(var v in miniViews)if(v&&v.gameObject.activeSelf){if(MiniPosition(v.World,actor.transform.position,out var point)){v.Rect.anchoredPosition=point;v.Rect.localScale=Vector3.one;// Minimap glyphs stay on their geographic anchors; threshold-based avoidance caused a visible jump near quest NPCs.
 v.SetOffset(0);}else v.gameObject.SetActive(false);}if(mini.Arrow)mini.Arrow.SetAsLastSibling();}}
  void Refresh(bool mapOpen,Vector3 player){if(mapOpen)Paint(worldViews,worldLayer,Groups(false,player),false);else Hide(worldViews);if(miniLayer)Paint(miniViews,miniLayer,Groups(true,player),true);}
  List<Group> Groups(bool small,Vector3 player){var groups=new List<Group>();foreach(var e in entries.OrderByDescending(e=>e.Priority).ThenBy(e=>(e.World-player).sqrMagnitude).ThenBy(e=>e.Key,StringComparer.Ordinal)){Vector2 point;if(small){if(!MiniPosition(e.World,player,out point))continue;}else if(!field.TryPosition(e.World,out point))continue;var parent=small?mini.Map.rectTransform:field.Content;var screen=(Vector2)RectTransformUtility.WorldToScreenPoint(null,parent.TransformPoint(point));var group=groups.FirstOrDefault(g=>(g.Pixel-screen).sqrMagnitude<(small?19:25)*(small?19:25));if(group==null){if(groups.Count>=(small?MinimapLimit:MapLimit))continue;group=new Group{Main=e,Pixel=screen};groups.Add(group);}group.Items.Add(e);}return groups;}
  void Paint(List<RiftQuestMapPinView> views,RectTransform parent,List<Group> groups,bool small){for(int i=0;i<groups.Count;i++){while(views.Count<=i){var go=new GameObject("Quest pin",typeof(RectTransform));var view=go.AddComponent<RiftQuestMapPinView>();view.Initialize(parent,small,font);views.Add(view);}var g=groups[i];int count=g.Items.Sum(e=>e.Count);string title=g.Items.Count==1?g.Main.Title:"Misiones cercanas · "+count;string body=string.Join("\n\n",g.Items.Take(6).Select(e=>g.Items.Count>1?e.Title+"\n"+e.Description:e.Description));if(g.Items.Count>6)body+="\n+"+(g.Items.Count-6)+" ubicaciones cercanas";string key=string.Join("|",g.Items.Select(e=>e.Key).OrderBy(x=>x,StringComparer.Ordinal));var v=views[i];v.Bind(key,g.Main.World,g.Main.Kind,title,body,count);Vector2 position;if(small)MiniPosition(g.Main.World,ClientFrontend.ClientPlayerInstance.MyCharacter.transform.position,out position);else field.TryPosition(g.Main.World,out position);v.Rect.anchoredPosition=position;v.Rect.localScale=small?Vector3.one:Vector3.one/Mathf.Max(.01f,field.Content.localScale.x);}for(int i=groups.Count;i<views.Count;i++)views[i].gameObject.SetActive(false);}
  bool MiniPosition(Vector3 world,Vector3 player,out Vector2 point){point=default;if(!mini||!mini.Map)return false;float range=mini.Theme?mini.Theme.MinimapRange:64;if(float.IsNaN(range)||float.IsInfinity(range)||range<4)range=64;var rect=mini.Map.rectTransform.rect;var delta=new Vector2(world.x-player.x,world.z-player.z);point=new Vector2(delta.x/(2*range)*rect.width,delta.y/(2*range)*rect.height);float radius=Mathf.Min(rect.width,rect.height)*.5f-12;return radius>0&&point.sqrMagnitude<=radius*radius;}
  static void Hide(List<RiftQuestMapPinView> views){foreach(var v in views)if(v&&v.gameObject.activeSelf)v.gameObject.SetActive(false);}
 }
